import scurange = require( './index' );


// TESTS //

// The function returns a Float32Array...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange( x.length, x, 1, y, 1 ); // $ExpectType Float32Array
}

// The compiler throws an error if the first argument is not a number...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange( '10', x, 1, y, 1 ); // $ExpectError
	scurange( true, x, 1, y, 1 ); // $ExpectError
	scurange( null, x, 1, y, 1 ); // $ExpectError
	scurange( {}, x, 1, y, 1 ); // $ExpectError
}

// The compiler throws an error if the second argument is not a Float32Array...
{
	const y = new Float32Array( 10 );

	scurange( 10, 10, 1, y, 1 ); // $ExpectError
	scurange( 10, 'x', 1, y, 1 ); // $ExpectError
	scurange( 10, [], 1, y, 1 ); // $ExpectError
}

// The compiler throws an error if the third argument is not a number...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange( 10, x, '1', y, 1 ); // $ExpectError
	scurange( 10, x, null, y, 1 ); // $ExpectError
}

// The compiler throws an error if the fourth argument is not a Float32Array...
{
	const x = new Float32Array( 10 );

	scurange( 10, x, 1, 10, 1 ); // $ExpectError
	scurange( 10, x, 1, {}, 1 ); // $ExpectError
}

// The compiler throws an error if the fifth argument is not a number...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange( 10, x, 1, y, '1' ); // $ExpectError
	scurange( 10, x, 1, y, null ); // $ExpectError
}

// The compiler throws an error for unsupported arity...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange(); // $ExpectError
	scurange( 10 ); // $ExpectError
	scurange( 10, x ); // $ExpectError
	scurange( 10, x, 1 ); // $ExpectError
	scurange( 10, x, 1, y ); // $ExpectError
	scurange( 10, x, 1, y, 1, 0 ); // $ExpectError
}


// ndarray METHOD //

// The ndarray method returns a Float32Array...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange.ndarray( x.length, x, 1, 0, y, 1, 0 ); // $ExpectType Float32Array
}

// ndarray argument validation...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange.ndarray( '10', x, 1, 0, y, 1, 0 ); // $ExpectError
	scurange.ndarray( 10, x, '1', 0, y, 1, 0 ); // $ExpectError
	scurange.ndarray( 10, x, 1, '0', y, 1, 0 ); // $ExpectError
	scurange.ndarray( 10, x, 1, 0, 10, 1, 0 ); // $ExpectError
	scurange.ndarray( 10, x, 1, 0, y, '1', 0 ); // $ExpectError
	scurange.ndarray( 10, x, 1, 0, y, 1, '0' ); // $ExpectError
}

// ndarray unsupported arity...
{
	const x = new Float32Array( 10 );
	const y = new Float32Array( 10 );

	scurange.ndarray(); // $ExpectError
	scurange.ndarray( 10, x ); // $ExpectError
	scurange.ndarray( 10, x, 1, 0, y, 1, 0, 10 ); // $ExpectError
}
